/**
 * @name Unvalidated socket connection to user-controlled address
 * @description Connecting to addresses without proper validation could lead to SSRF
 * @kind path-problem
 * @problem.severity warning
 * @id py/unvalidated-socket-connection
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SocketConnectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to public functions that accept addresses
    exists(Function f, Parameter p |
      f.isPublic() and
      p = f.getAnArg() and
      p.getName() in ["host", "addr", "address", "hostname"] and
      source.(DataFlow::ParameterNode).getParameter() = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Socket connection calls
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember("create_connection").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("asyncio").getMember("open_connection").getACall() and
      sink = call.getArg(0)
    )
    or
    // Direct socket connect calls
    exists(DataFlow::CallCfgNode call, DataFlow::AttrRead attr |
      attr.getAttributeName() = "connect" and
      call.getFunction() = attr and
      sink = call.getArg(0)
    )
  }
}

module SocketConnectionFlow = TaintTracking::Global<SocketConnectionConfig>;
import SocketConnectionFlow::PathGraph

from SocketConnectionFlow::PathNode source, SocketConnectionFlow::PathNode sink
where SocketConnectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Socket connection to potentially unvalidated address from $@.", source.getNode(), "user input"

/**
 * @name Potential SSRF via socket operations
 * @description User-controlled data flowing to socket operations may allow SSRF attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/ssrf-socket
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to public functions
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Socket connect operations
      call = API::moduleImport("socket").getMember("socket").getReturn().getMember("connect").getACall() and
      sink = call.getArg(_)
      or
      // Socket create_connection
      call = API::moduleImport("socket").getMember("create_connection").getACall() and
      sink = call.getArg(_)
      or
      // asyncio open_connection
      call = API::moduleImport("asyncio").getMember("open_connection").getACall() and
      sink = call.getArg(_)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Socket operation uses potentially untrusted data from $@.", source.getNode(), "user input"
